## Defines the start times for the partials of an additive synthesis note. This responds to the#fact that not all harmonics start resonating at the beginning of the note (higher and less#consonant partials take more time to begin vibrating).from random import expovariatedef comienzos(espectro_dist, limit=.5):		ataques		= [0]	contador	= len(espectro_dist) - 1		while contador >0:		un_ataque = expovariate(2)	####Play with this value when there's sound		if un_ataque <= limit and un_ataque >= .001:			ataques.append(un_ataque)			contador = contador - 1	ataques.sort()	return ataques